class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        def operations_needed(n):
            """Returns number of operations to reduce n to 0 using floor(n/4)"""
            if n < 4:
                return 0
            ops = 0
            while n >= 4:
                n //= 4
                ops += 1
            return ops

        result = 0
        for l, r in queries:
            total_operations = 0
            for i in range(l, r+1):
                total_operations += operations_needed(i)
            result += total_operations
        return result

