    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        def canMakeZero(k):
            # Build difference array for first k queries
            diff = [0] * (len(nums) + 1)

            # Apply segment updates
            for i in range(k):
                l, r, val = queries[i]
                diff[l] += val
                diff[r + 1] -= val

            # Convert to prefix sum to get actual decrements
            decrements = [0] * len(nums)
            decrements[0] = diff[0]
            for i in range(1, len(nums)):
                decrements[i] = diff[i] + decrements[i-1]

            # For the array to become all zeros, 
            # each element must have at least as many decrements as its value
            for i in range(len(nums)):
                if nums[i] < decrements[i]:
                    return False
            return True

        # Binary search for the minimum k
        left, right = 0, len(queries)
        result = -1

        while left <= right:
            mid = (left + right) // 2
            if canMakeZero(mid):
                result = mid
                right = mid - 1
            else:
                left = mid + 1

        return result

