import heapq

def main():
    # Read input
    N, M, X = map(int, input().split())

    # Build adjacency lists
    adj = [[] for _ in range(N + 1)]

    for _ in range(M):
        u, v = map(int, input().split())
        adj[u].append(v)

    # Create reverse adjacency list
    adj_rev = [[] for _ in range(N + 1)]
    for u in range(1, N + 1):
        for v in adj[u]:
            adj_rev[v].append(u)

    # Dijkstra with state: (cost, vertex, reversed_state)
    # reversed_state = 0 (normal) or 1 (reversed)
    pq = [(0, 1, 0)]  # (cost, vertex, reversed_state)

    # Keep track of min cost to reach (vertex, reversed_state)
    min_cost = {}

    while pq:
        cost, vertex, reversed_state = heapq.heappop(pq)

        if vertex == N:
            print(cost)
            return

        # Skip if we've already found a better path to this state
        if (vertex, reversed_state) in min_cost and min_cost[(vertex, reversed_state)] <= cost:
            continue
        min_cost[(vertex, reversed_state)] = cost

        # Move along edges in the current graph (cost 1)
        if reversed_state == 0:
            # Current graph is normal
            for next_vertex in adj[vertex]:
                heapq.heappush(pq, (cost + 1, next_vertex, 0))
        else:
            # Current graph is reversed
            for next_vertex in adj_rev[vertex]:
                heapq.heappush(pq, (cost + 1, next_vertex, 1))

        # Reverse the graph (cost X)
        heapq.heappush(pq, (cost + X, vertex, 1 - reversed_state))

